package br.com.confirmacao.professional.location.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="professional_locations") public class ProfessionalLocation{@Id @Column(name="professional_id") private UUID professionalId;@Column(nullable=false,length=100)private String city;@Column(nullable=false,length=2)private String state;@Column(nullable=false,length=60)private String timezone;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected ProfessionalLocation(){}public ProfessionalLocation(UUID id,String city,String state,String timezone){professionalId=id;update(city,state,timezone);}public void update(String city,String state,String timezone){this.city=city.trim();this.state=state.trim().toUpperCase();this.timezone=timezone.trim();updatedAt=Instant.now();}public UUID getProfessionalId(){return professionalId;}public String getCity(){return city;}public String getState(){return state;}public String getTimezone(){return timezone;}}
